// Left-bound binary search: finds first index where condition is true
// Most general form - works for 'first occurrence', 'search insert position', answer space
function leftBound(arr, target) {
  let left = 0;
  let right = arr.length; // note: n, not n-1

  while (left < right) { // note: strict less than
    const mid = left + Math.floor((right - left) / 2);
    if (arr[mid] >= target) {
      right = mid;         // mid could be the answer; keep it in range
    } else {
      left = mid + 1;      // mid is too small; advance left past it
    }
  }
  return left; // left === right when loop exits; this is the first valid index
}

// Binary search on answer space
// Example: minimum capacity to ship packages in D days
function shipWithinDays(weights, days) {
  // Binary search bounds: min capacity = heaviest package, max = sum of all
  let left = Math.max(...weights);
  let right = weights.reduce((a, b) => a + b, 0);

  while (left < right) {
    const mid = left + Math.floor((right - left) / 2);
    if (canShip(weights, days, mid)) {
      right = mid;   // mid capacity works; try smaller
    } else {
      left = mid + 1; // mid too small; need more capacity
    }
  }
  return left;
}

function canShip(weights, days, capacity) {
  let daysNeeded = 1;
  let current = 0;
  for (const w of weights) {
    if (current + w > capacity) { daysNeeded++; current = 0; }
    current += w;
  }
  return daysNeeded <= days;
}
